namespace Railroader.ModManager.Interfaces;

/// <summary> Represents a loaded mod instance. </summary>
[PublicAPI]
public interface IMod
{
    /// <summary> Gets the definition/metadata for this mod. </summary>
    IModDefinition Definition { get; }

    /// <summary> Gets a value indicating whether this mod is enabled. </summary>
    bool IsEnabled { get; }

    /// <summary> Gets a value indicating whether this mod is valid. </summary>
    bool IsValid { get; }

    /// <summary> Gets a value indicating whether this mod is loaded. </summary>
    bool IsLoaded { get; }

    /// <summary> Gets the plugins provided by this mod, or <see langword="null"/> if no plugins are available. </summary>
    IPlugin[]? Plugins { get; }

    /// <summary> Creates a scoped logger for this mod. </summary>
    /// <param name="scope">
    /// The optional scope name to append to the logger context.
    /// If <see langword="null"/>, only the mod identifier is used.
    /// </param>
    /// <returns>A configured logger instance.</returns>
    ILogger CreateLogger(string? scope = null);
}

using System;
using System.Collections.Generic;
using JetBrains.Annotations;
using Serilog.Events;

namespace Railroader.ModManager.Interfaces;

/// <summary> Defines the metadata for a mod. Loaded from Definition.json </summary>
[PublicAPI]
public interface IModDefinition
{
    /// <summary> Gets the unique identifier for the mod. </summary>
    string Identifier { get; }

    /// <summary> Gets the display name of the mod. </summary>
    string Name { get; }

    /// <summary> Gets the version of the mod. </summary>
    /// <remarks> The version specifies the mod's release in a format compatible with <see cref="System.Version"/>, typically in the form Major.Minor.Build (e.g., "1.0.0"). </remarks>
    Version Version { get; }

    /// <summary> Gets the preferred logging level for the mod, or <see langword="null"/> to use <see cref="LogEventLevel.Information"/>. </summary>
    LogEventLevel? LogLevel { get; }

    /// <summary>Gets the dictionary of mod identifiers and their required version constraints that this mod depends on.</summary>
    /// <remarks>
    /// Each key is a mod identifier, and each value is a <see cref="FluentVersion"/> specifying the version constraint, or <c>null</c> to indicate any version is acceptable.
    /// In JSON deserialization:
    /// <list type="bullet">
    ///   <item>A version string without an operator (e.g., <c>"1.0.1"</c>) sets <see cref="FluentVersion.Operator"/> to <see cref="VersionOperator.GreaterOrEqual"/> and <see cref="FluentVersion.Version"/> to the parsed version.</item>
    ///   <item>An empty string (e.g., <c>""</c>) results in a <c>null</c> value in the dictionary, indicating any version of the mod is acceptable.</item>
    ///   <item>A string with an operator (e.g., <c>"=1.0.1"</c>, <c>"&gt;=1.0.1"</c>, <c>"&lt;2.0.0"</c>) sets the corresponding <see cref="FluentVersion.Operator"/> and <see cref="FluentVersion.Version"/>.</item>
    /// </list>
    /// For example, <c>"foo": "1.0.1"</c> requires mod "foo" with version 1.0.1 or higher, <c>"foo": "=1.0.1"</c> requires exactly version 1.0.1, and <c>"foo": ""</c> requires mod "foo" with any version. Version strings must be valid <see cref="System.Version"/> formats, except for the empty string case.
    /// </remarks>
    Dictionary<string, FluentVersion?>? Requires { get; }

    /// <summary>Gets the dictionary of mod identifiers and their version constraints that this mod conflicts with.</summary>
    /// <remarks>
    /// Each key is a mod identifier, and each value is a <see cref="FluentVersion"/> specifying the incompatible version constraint, or <c>null</c> to indicate any version is incompatible.
    /// In JSON deserialization:
    /// <list type="bullet">
    ///   <item>A version string without an operator (e.g., <c>"1.2.3"</c>) sets <see cref="FluentVersion.Operator"/> to <see cref="VersionOperator.GreaterOrEqual"/>, meaning versions at or above the specified version are incompatible.</item>
    ///   <item>An empty string (e.g., <c>""</c>) results in a <c>null</c> value in the dictionary, indicating any version of the mod is incompatible.</item>
    ///   <item>A string with an operator (e.g., <c>"=1.0.1"</c>, <c>"&lt;1.2.3"</c>, <c>"&gt;1.0.1"</c>) sets the corresponding <see cref="FluentVersion.Operator"/> and <see cref="FluentVersion.Version"/>.</item>
    /// </list>
    /// For example, <c>"second": "&lt;1.2.3"</c> means versions of mod "second" less than 1.2.3 are incompatible, <c>"second": "=1.0.1"</c> means only version 1.0.1 is incompatible, and <c>"second": ""</c> means any version of mod "second" is incompatible.
    /// Version strings must be valid <see cref="System.Version"/> formats, except for the empty string case.
    /// </remarks>
    Dictionary<string, FluentVersion?>? ConflictsWith { get; }
}

using System;
using System.Collections.Generic;
using UI.Builder;
using UI.Common;

namespace Railroader.ModManager.Interfaces;

/// <summary> An injectable interface that allows access to other mods and some quality-of-life functionality. </summary>
public interface IModdingContext
{
    /// <summary> Gets the list of all mods. This includes loaded, enabled, disabled, and failed mods. </summary>
    IReadOnlyCollection<IMod> Mods { get; }

    /// <summary> Loads the settings with the identifier, which is ideally the mod's id. </summary>
    /// <typeparam name="T">The type that the settings should be deserialized as.</typeparam>
    /// <param name="identifier">The identifier that identifies which settings should be loaded. Only letters (a-z) and digits (0-9) are allowed here.</param>
    /// <returns>The settings if an instance could be found; <see langword="null" /> otherwise.</returns>
    T? LoadSettings<T>(string identifier) where T : class;

    /// <summary> Saves the settings with the specified identifier. </summary>
    /// <param name="identifier">The identifier that identifies which settings should be loaded. Only letters (a-z) and digits (0-9) are allowed here.</param>
    /// <param name="settings">The settings that should be serialized. This class must be JSON-serializable.</param>
    void SaveSettings<T>(string identifier, T settings) where T : class;

    /// <summary> Creates a new window. </summary>
    /// <param name="identifier">The identifier for this window</param>
    /// <param name="width">Width of the window to create</param>
    /// <param name="height">Height of the window to create</param>
    /// <param name="position">Position that the window should be created at</param>
    /// <returns>The created window instance.</returns>
    Window CreateWindow(string identifier, int width, int height, Window.Position position);

    /// <summary> Populates a window with a builder. </summary>
    /// <param name="window">Window to populate.</param>
    /// <param name="closure">Callback for the builder to build the window's contents.</param>
    /// <returns>The created UI panel.</returns>
    UIPanel PopulateWindow(Window window, Action<UIPanelBuilder> closure);
}

using JetBrains.Annotations;

namespace Railroader.ModManager.Interfaces;

/// <summary> Defines the contract for plugins in the modding system, providing access to modding context and mod metadata. </summary>
/// <remarks>
/// This interface is intended to be implemented only by classes derived from <see cref="PluginBase{T}"/>.
/// Direct implementation by other classes is not supported, as the modding system relies on the singleton
/// and initialization logic provided by <see cref="PluginBase{T}"/>.
/// </remarks>
[PublicAPI]
public interface IPlugin
{
    /// <summary> Gets the modding context for this plugin. </summary>
    IModdingContext ModdingContext { get; }

    /// <summary> Gets the mod for this plugin. </summary>
    IMod Mod { get; }

    /// <summary> Gets or sets a value indicating whether this plugin is enabled. </summary>
    bool IsEnabled { get; set; }
}

