    /// <item><c>$arg$</c> - single argument</item>
    /// <item><c>$arg1$ ... $arg10$</c> - single argument</item>
    /// <item><c>$stmts$</c> - any number of statements</item>
    /// <item><c>$stmt$</c> - single statement</item>
    /// <item><c>$stmt1$ ... $stmt10$</c> - single statement</item>
