    [JsonConverter(typeof(ModReferenceJsonConverter))]
    public Dictionary<string, FluentVersion?>? Requires { get; set; }

    /// <inheritdoc />
    [JsonProperty("conflictsWith")]
    [JsonConverter(typeof(ModReferenceJsonConverter))]
    public Dictionary<string, FluentVersion?>? ConflictsWith { get; set; }

