namespace MemoryFileSystem;

public interface IMemoryFs : IMemoryFileSystem
{
    string CurrentDirectory { get; set; }
}

public sealed class MemoryFs : MemoryFileSystem, IMemoryFs
{
    public MemoryFs(string? currentDirectory = null) => CurrentDirectory = currentDirectory ?? "C:\\";

    private string _CurrentDirectory = null!;

    public string CurrentDirectory {
        get => _CurrentDirectory;
        [ExcludeFromCodeCoverage]
        set {
            var normalized = NormalizePath(value);
            VerifyParents(normalized);
            _CurrentDirectory = normalized;
        }
    }

    public override string NormalizePath(string path) {
        if (string.IsNullOrEmpty(path)) {
            throw new ArgumentException("Path cannot be null or empty.");
        }

        // Resolve relative paths against _currentDirectory
        if (!Path.IsPathRooted(path)) {
            path = Path.Combine(CurrentDirectory, path);
        }

        path = Path.GetFullPath(path);
        if (path.Length > 3) { // Trim trailing slash for non-root paths
            path = path.TrimEnd('\\');
        }

        return path;
    }

    protected override string? GetParentPath(string path) => Path.GetDirectoryName(path);
}

using System;
using System.Linq;
using System.Text;
using MemoryFileSystem.Types;
using Newtonsoft.Json;

namespace MemoryFileSystem;

public interface IMemoryZip : IMemoryFileSystem
{
    byte[] GetBytes();
}

public sealed class MemoryZip : MemoryFileSystem, IMemoryZip
{
    public MemoryZip() {
    }

    public MemoryZip(byte[] bytes) {
        var entries = GetEntries(bytes);

        foreach (var entry in entries) {
            Items.TryAdd(entry.Path, entry);
        }
    }

    public override string NormalizePath(string path) {
        if (string.IsNullOrEmpty(path)) {
            throw new ArgumentException("Path cannot be null or empty.");
        }

        if (path.Contains(':')) {
            throw new ArgumentException("Zip file do not support absolute paths.");
        }

        path = path.Replace('\\', '/');
        if (path.StartsWith("/")) {
            path = path.Substring(1); // Remove leading "/"
        }

        return path;
    }

    protected override string? GetParentPath(string path) {
        var index = path.LastIndexOf('/');
        return index == -1 ? null : path.Substring(0, index);
    }

    public byte[] GetBytes() => Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(Items.Values.ToArray()));

    private static MemoryEntry[] GetEntries(byte[] bytes) => JsonConvert.DeserializeObject<MemoryEntry[]>(Encoding.UTF8.GetString(bytes))!;
}

