        logger.Received().Information("No patches were applied to assembly {AssemblyPath} for mod {ModId}", AssemblyPath, "DummyMod");
        logger.Received().Error("Failed to apply patches to assembly {AssemblyPath} for mod {ModId}", AssemblyPath, _ModDefinition.Identifier);
        logger.ShouldReceiveCallCount(4);

        readAssemblyDefinition.Received(1).Invoke(AssemblyPath,
                                                  Arg.Is<ReaderParameters>(o =>
                                                                               o.AssemblyResolver is DefaultAssemblyResolver &&
                                                                               ((DefaultAssemblyResolver)o.AssemblyResolver).GetSearchDirectories()!.SequenceEqual(expectedDirectories)
                                                  )
        );
        writeAssemblyDefinition.Received(0).Invoke(Arg.Any<AssemblyDefinition>(), Arg.Any<string>());
    }

    [Fact]
    public void ApplyPatches_EmptyRequires_DoesNotScanModsDirectory()
    {
        // Arrange
        var modDefinition = new ModDefinition
        {
            Identifier = "EmptyRequiresMod",
            BasePath   = @"C:\Current\Mods\EmptyRequiresMod",
            Requires   = new Dictionary<string, FluentVersion?>() // Count = 0
        };

        var assemblyPath = Path.Combine(modDefinition.BasePath, "EmptyRequiresMod.dll");

        var fileSystem = new MemoryFs(@"\Current")
        {
            { assemblyPath, "", _OldDate },
            { @"C:\Current\Mods\OtherMod\OtherMod.dll", "", _OldDate }
        };

        var logger        = Substitute.For<ILogger>();
        var readAssembly  = Substitute.For<ReadAssemblyDefinition>();
        var writeAssembly = Substitute.For<WriteAssemblyDefinition>();

        // Return a minimal assembly with no types
        var (assemblyDef, _) = TestUtils.BuildAssemblyDefinition("namespace Test { public class Dummy {} }");
        readAssembly.Invoke(Arg.Any<string>(), Arg.Any<ReaderParameters>()).Returns(assemblyDef);

        var applyPatches = Factory(logger, fileSystem, readAssembly, writeAssembly);

        // Act
        var result = applyPatches(modDefinition, CodePatcher.DefaultPluginPatchers);

        // Assert
        result.ShouldBeTrue();

        // Resolver should NOT include any mod directories
        readAssembly.Received(1).Invoke(
            assemblyPath,
            Arg.Is<ReaderParameters>(p =>
                                         p.AssemblyResolver is DefaultAssemblyResolver &&
                                         ((DefaultAssemblyResolver)p.AssemblyResolver).GetSearchDirectories().Length == 3 && // ., bin, Managed
                                         ((DefaultAssemblyResolver)p.AssemblyResolver).GetSearchDirectories().Contains(@"C:\Current\Mods\OtherMod") == false
            )
        );

        // No file operations
        fileSystem.File.Delete.DidNotReceive().Invoke(Arg.Any<string>());
        fileSystem.File.Move.DidNotReceive().Invoke(Arg.Any<string>(), Arg.Any<string>());
    }

    private static class TestPluginPatcher
    {
        public static TypePatcherDelegate Factory() => (_, _) => true;
    }

    private static class ThrowingPatcher
    {
        public static TypePatcherDelegate Factory() => (_, _) => throw new("ThrowingPatcher");
    }
