using System;
using System.Linq;
using NSubstitute;
using NSubstitute.ExceptionExtensions;
using Railroader.ModManager.Delegates.System.Reflection.Assembly;
using Railroader.ModManager.Features;
using Railroader.ModManager.Interfaces;
using Serilog;
using Shouldly;

namespace Railroader.ModManager.Tests.Features;

public sealed class TestsPluginManager {
    private const string AssemblyPath = @"Mod\Dummy\Dummy.dll";

    private static Mod CreateMod(ILogger logger) {
        var modDefinition = Substitute.For<IModDefinition>();
        modDefinition.Identifier.Returns("Identifier");
        return new(logger, modDefinition) { AssemblyPath = AssemblyPath };
    }

    [Fact]
    public void CreatePlugins_WhenAssemblyFailsToLoad() {
        // Arrange
        var logger         = Substitute.For<ILogger>();
        var moddingContext = Substitute.For<IModdingContext>();
        var loadFrom       = Substitute.For<LoadFrom>();
        var mod            = CreateMod(logger);

        // Act
        var plugins = PluginManager.LoadPlugins(moddingContext, logger, loadFrom, mod);

        // Assert
        plugins.ShouldBeEmpty();
        logger.Received().Warning("Failed to load assembly from path: {AssemblyPath} for mod {ModId}", @"Mod\Dummy\Dummy.dll", "Identifier");
    }

    [Fact]
    public void CreatePlugins_WhenAssemblyNull() {
        // Arrange
        var logger         = Substitute.For<ILogger>();
        var moddingContext = Substitute.For<IModdingContext>();
        var loadFrom       = Substitute.For<LoadFrom>();
        var mod            = CreateMod(logger);
        mod.AssemblyPath = null;

        // Act & Assert
        Should.Throw<InvalidOperationException>(() => PluginManager.LoadPlugins(moddingContext, logger, loadFrom, mod))
              .Message.ShouldBe("Mod contract violation: AssemblyPath is null.");
    }

    [Fact]
    public void CreatePlugins_IgnoreAbstractClasses() {
        // Arrange
        const string source =
            """
            using Railroader.ModManager.Interfaces;

            public abstract class Foo  {};

            public abstract class Bar : PluginBase<Bar> {
                public Bar(IModdingContext moddingContext, IMod mod) 
                    : base(moddingContext, mod) {
                }
            };
            """;

        var assembly = TestUtils.BuildAssembly(source, [typeof(TestsPluginManager).Assembly.GetName().Name]);

        var logger         = Substitute.For<ILogger>();
        var moddingContext = Substitute.For<IModdingContext>();
        var loadFrom       = Substitute.For<LoadFrom>();
        loadFrom.Invoke(Arg.Any<string>()).Returns(assembly);
        var mod = CreateMod(logger);

        // Act
        var plugins = PluginManager.LoadPlugins(moddingContext, logger, loadFrom, mod);

        // Assert
        plugins.ShouldBeEmpty();
    }

    [Fact]
    public void CreatePlugins_IgnoreClassesNotDerivedFromPluginBase() {
        // Arrange
        const string source =
            """
            public class Foo {
            }
            """;

        var assembly = TestUtils.BuildAssembly(source, [typeof(TestsPluginManager).Assembly.GetName().Name]);

        var logger         = Substitute.For<ILogger>();
        var moddingContext = Substitute.For<IModdingContext>();
        var loadFrom       = Substitute.For<LoadFrom>();
        loadFrom.Invoke(Arg.Any<string>()).Returns(assembly);
        var mod = new Mod(logger, Substitute.For<IModDefinition>()) {
            AssemblyPath = AssemblyPath
        };

        // Act
        var plugins = PluginManager.LoadPlugins(moddingContext, logger, loadFrom, mod);

        // Assert
        plugins.ShouldBeEmpty();
    }

    [Fact]
    public void CreatePlugins_IgnoreClassesNotDerivedFromPluginBase_AndWarnIfIPluginBaseIsImplemented() {
        // Arrange
        const string source =
            """
            using Railroader.ModManager.Interfaces;

            public class Foo : IPlugin {
                public IModdingContext ModdingContext { get; }
                public IMod Mod { get; }
                public bool IsEnabled { get; set; }
                
                public Foo(IModdingContext moddingContext, IMod mod) {
                }
            }
            """;

        var assembly = TestUtils.BuildAssembly(source, [typeof(TestsPluginManager).Assembly.GetName().Name]);

        var logger         = Substitute.For<ILogger>();
        var moddingContext = Substitute.For<IModdingContext>();
        var loadFrom       = Substitute.For<LoadFrom>();
        loadFrom.Invoke(Arg.Any<string>()).Returns(assembly);
        var mod = CreateMod(logger);

        // Act
        var plugins = PluginManager.LoadPlugins(moddingContext, logger, loadFrom, mod);

        // Assert
        plugins.ShouldBeEmpty();
        logger.Received().Warning("Type {Type} implements IPlugin but does not inherit from PluginBase<> in mod {ModId}", "Foo", "Identifier");
    }

    [Theory]
    [InlineData("""
        using Railroader.ModManager.Interfaces;
        using Serilog;

        public sealed class TestPlugin : PluginBase<TestPlugin>
        {
            public TestPlugin() 
                : base(null, null) {
            }
        }
        """)]
    [InlineData("""
        using Railroader.ModManager.Interfaces;
        using Serilog;

        public sealed class TestPlugin : PluginBase<TestPlugin>
        {
            public TestPlugin(IModdingContext moddingContext, IMod mod, int extra) 
                : base(moddingContext, mod) {
            }
        }
        """)]
    public void CreatePlugins_IgnorePluginsWithInvalidConstructor(string source) {
        // Arrange
        var assembly = TestUtils.BuildAssembly(source, [typeof(TestsPluginManager).Assembly.GetName().Name]);

        var logger         = Substitute.For<ILogger>();
        var moddingContext = Substitute.For<IModdingContext>();
        var loadFrom       = Substitute.For<LoadFrom>();
        loadFrom.Invoke(Arg.Any<string>()).Returns(assembly);
        var mod = CreateMod(logger);

        // Act
        var plugins = PluginManager.LoadPlugins(moddingContext, logger, loadFrom, mod);

        // Assert
        plugins.ShouldBeEmpty();
        logger.Received().Warning("Cannot find constructor (IModdingContext, IMod) on plugin {Plugin} in mod {ModId}", "TestPlugin", "Identifier");
    }

    [Fact]
    public void CreatePlugins_ReturnValidInstances() {
        // Arrange
        const string source =
            """
            using Railroader.ModManager.Interfaces;
            using Serilog;

            namespace Foo.Bar
            {
                public sealed class FirstPlugin : PluginBase<FirstPlugin>
                {
                    public FirstPlugin(IModdingContext moddingContext, IMod mod) 
                        : base(moddingContext, mod) {
                    }
                }
                
                public sealed class SecondPlugin : PluginBase<SecondPlugin>
                {
                    public SecondPlugin(IModdingContext moddingContext, IMod mod) 
                        : base(moddingContext, mod) {
                    }
                }
            }
            """;

        var assembly = TestUtils.BuildAssembly(source, [typeof(TestsPluginManager).Assembly.GetName().Name]);

        var logger         = Substitute.For<ILogger>();
        var moddingContext = Substitute.For<IModdingContext>();
        var loadFrom       = Substitute.For<LoadFrom>();
        loadFrom.Invoke(Arg.Any<string>()).Returns(assembly);
        var mod = CreateMod(logger);

        // Act
        var plugins = PluginManager.LoadPlugins(moddingContext, logger, loadFrom, mod);

        // Assert
        plugins.Select(o => o.GetType().FullName).ToArray().ShouldBeEquivalentTo(new[] { "Foo.Bar.FirstPlugin", "Foo.Bar.SecondPlugin" });
    }
}

using Newtonsoft.Json;
using Railroader.ModManager.JsonConverters;
using Serilog.Events;
using Shouldly;

namespace Railroader.ModManager.Tests.JsonConverters;

public sealed class TestsLogEventLevelJsonConverter
{
    [Theory]
    [InlineData("""{ "logLevel": "Verbose" }""", LogEventLevel.Verbose)]
    [InlineData("""{ "logLevel": "Debug" }""", LogEventLevel.Debug)]
    [InlineData("""{ "logLevel": "Information" }""", LogEventLevel.Information)]
    [InlineData("""{ "logLevel": "Warning" }""", LogEventLevel.Warning)]
    [InlineData("""{ "logLevel": "Error" }""", LogEventLevel.Error)]
    [InlineData("""{ "logLevel": "Fatal" }""", LogEventLevel.Fatal)]
    [InlineData("""{ "logLevel": "FaTaL" }""", LogEventLevel.Fatal)]
    [InlineData("""{ "logLevel": null }""", null!)]
    [InlineData("{ }", null!)]
    public void ReadValidJson(string json, LogEventLevel? expected) {
        // Act
        var actual = JsonConvert.DeserializeObject<TestData>(json);

        // Assert
        actual.ShouldNotBeNull();
        actual.LogLevel.ShouldBe(expected);
    }

    [Fact]
    public void ReadInvalidValue() {
        // Act & Assert
        Should.Throw<JsonReaderException>(() => JsonConvert.DeserializeObject<TestData>("""{ "logLevel": "invalid" }"""))
              .Message.ShouldBe($"Unexpected token value 'invalid' when reading {typeof(LogEventLevel?)}. Expected: 'Verbose', 'Debug', 'Information', 'Warning', 'Error', 'Fatal' or null");
    }

    [Fact]
    public void ReadInvalidType() {
        // Act & Assert
        Should.Throw<JsonReaderException>(() => JsonConvert.DeserializeObject<TestData>("""{ "logLevel": 42 }"""))
              .Message.ShouldBe($"Unexpected token type {JsonToken.Integer} when reading {typeof(LogEventLevel?)}. Expected: {JsonToken.Null} or {JsonToken.String}.");
    }

    [Fact]
    public void WriteJsonNotSupported() {
        // Act
        var actual = JsonConvert.SerializeObject(new TestData { LogLevel = LogEventLevel.Debug });

        // Assert
        actual.ShouldBe("""{"logLevel":"Debug"}""");
    }

    private sealed class TestData
    {
        [JsonProperty("logLevel")]
        [JsonConverter(typeof(LogEventLevelJsonConverter))]
        public LogEventLevel? LogLevel { get; set; }
    }
}

using System;
using System.Collections.Generic;
using Newtonsoft.Json;
using Railroader.ModManager.Interfaces;
using Railroader.ModManager.JsonConverters;
using Shouldly;

namespace Railroader.ModManager.Tests.JsonConverters;

public sealed class TestsModReferenceJsonConverter
{
    private sealed class TestData
    {
        [JsonProperty("data")]
        [JsonConverter(typeof(ModReferenceJsonConverter))]
        public Dictionary<string, FluentVersion?> Data { get; set; } = null!;
    }

    [Theory]
    [InlineData("""{"data":{"foo":"1"}}""", VersionOperator.GreaterOrEqual, "1.0")]
    [InlineData("""{"data":{"foo":"1.0.0"}}""", VersionOperator.GreaterOrEqual, "1.0.0")]
    [InlineData("""{"data":{"foo": null }}""", null!, null!)]
    [InlineData("""{"data":{"foo": "" }}""", null!, null!)]
    [InlineData("""{"data":{"foo":"=1.0.1"}}""", VersionOperator.Equal, "1.0.1")]
    [InlineData("""{"data":{"foo":"= 1.0.1"}}""", VersionOperator.Equal, "1.0.1")]
    [InlineData("""{"data":{"foo":">1.0.0"}}""", VersionOperator.GreaterThan, "1.0.0")]
    [InlineData("""{"data":{"foo":"> 1.0.0"}}""", VersionOperator.GreaterThan, "1.0.0")]
    [InlineData("""{"data":{"foo":"<=2.0.0"}}""", VersionOperator.LessOrEqual, "2.0.0")]
    [InlineData("""{"data":{"foo":"<= 2.0.0"}}""", VersionOperator.LessOrEqual, "2.0.0")]
    [InlineData("""{"data":{"foo":"<1.2.3"}}""", VersionOperator.LessThan, "1.2.3")]
    [InlineData("""{"data":{"foo":"< 1.2.3"}}""", VersionOperator.LessThan, "1.2.3")]
    [InlineData("""{"data":{"foo":">=1.0.0"}}""", VersionOperator.GreaterOrEqual, "1.0.0")]
    [InlineData("""{"data":{"foo":">= 1.0.0"}}""", VersionOperator.GreaterOrEqual, "1.0.0")]
    public void ReadValidJson(string json, VersionOperator? @operator, string? versionString) {
        // Act
        var actual = JsonConvert.DeserializeObject<TestData>(json);

        // Assert
        actual.ShouldNotBeNull();
        actual.Data.ShouldNotBeNull();
        actual.Data.Count.ShouldBe(1);
        actual.Data.ShouldContainKey("foo");
        var fluentVersion = actual.Data["foo"];

        if (@operator == null) {
            fluentVersion.ShouldBeNull();
        } else {
            fluentVersion.ShouldNotBeNull();
            fluentVersion.Operator.ShouldBe(@operator.Value);
            fluentVersion.Version.ShouldBe(new Version(versionString!));
        }
    }

    [Theory]
    [InlineData("""{"data":{"foo":"invalid"}}""", "invalid")]
    [InlineData("""{"data":{"foo":"~1.0.1"}}""", "~1.0.1")]
    [InlineData("""{"data":{"foo":">"}}""", ">")]
    [InlineData("""{"data":{"foo":"<"}}""", "<")]
    [InlineData("""{"data":{"foo":">="}}""", ">=")]
    [InlineData("""{"data":{"foo":">=invalid"}}""", ">=invalid")]
    public void ReadInvalidJson(string json, string value) {
        // Act & Assert
        Should.Throw<JsonSerializationException>(() => JsonConvert.DeserializeObject<TestData>(json))
              .Message.ShouldBe($"Invalid version constraint '{value}' for mod 'foo'. Expected a valid System.Version or an operator (=, >, >=, <, <=) followed by a version.");
    }

    [Fact]
    public void ReadInvalidType() {
        // Arrange
        const string json = """{"data":{"foo":123}}""";

        // Act & Assert
        Should.Throw<JsonSerializationException>(() => JsonConvert.DeserializeObject<TestData>(json))
              .Message.ShouldBe($"Invalid version constraint for mod 'foo' in {typeof(Dictionary<string, FluentVersion>)}. Expected a string.");
    }

    [Fact]
    public void ReadNullDictionary() {
        // Arrange
        const string json = """{"data":null}""";

