        };

        var expected = new List<MemoryEntry> {
            new(@"c:\"),
            new(@"c:\bar"),
            new(@"c:\bar\file1.doc", [4, 5, 6]),
            new(@"c:\path"),
            new(@"c:\path\test"),
            new(@"c:\path\test\file2.txt", [1, 2, 3])
        };

        // Act
        using var enumerator = sut.GetEnumerator();

